package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// The journal owns exact source and generated bytes, including file absence.
// Copies next to the journal let users inspect unresolved recovery state.
type transaction struct {
	Version            int    `json:"version"`
	Phase              string `json:"phase"`
	Reload             bool   `json:"reload"`
	Migration          bool   `json:"migration"`
	PreviousSource     []byte `json:"previous_source"`
	CandidateSource    []byte `json:"candidate_source"`
	PreviousGenerated  []byte `json:"previous_generated"`
	CandidateGenerated []byte `json:"candidate_generated"`
	PreviousActive     []byte `json:"previous_active"`
	CandidateActive    []byte `json:"candidate_active"`
}

func syncDir(path string) error {
	dir, err := os.Open(path)
	if err != nil {
		return err
	}
	return errors.Join(dir.Sync(), dir.Close())
}

func atomicWrite(path string, data []byte) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".sandbar-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	_, writeErr := file.Write(data)
	syncErr := file.Sync()
	if err := errors.Join(writeErr, syncErr, file.Close()); err != nil {
		return err
	}
	if err := os.Rename(file.Name(), path); err != nil {
		return err
	}
	return syncDir(filepath.Dir(path))
}

func readOptional(path string) ([]byte, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	return data, err
}

func saveTransaction(p paths, tx transaction) error {
	dir := p.file("transaction")
	prepared := tx.Phase == "prepared"
	if prepared {
		if _, err := os.Lstat(dir); err == nil {
			return fmt.Errorf("recovery directory already exists: %s", dir)
		} else if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		staging, err := os.MkdirTemp(p.state, ".transaction-*")
		if err != nil {
			return err
		}
		defer os.RemoveAll(staging)
		dir = staging
		copies := []struct {
			name string
			data []byte
		}{
			{"previous.config.json", tx.PreviousSource}, {"candidate.config.json", tx.CandidateSource},
			{"previous.Caddyfile", tx.PreviousGenerated}, {"candidate.Caddyfile", tx.CandidateGenerated},
			{"previous.active.json", tx.PreviousActive}, {"candidate.active.json", tx.CandidateActive},
		}
		for _, copy := range copies {
			if copy.data == nil {
				continue
			}
			if err := atomicWrite(filepath.Join(dir, copy.name), copy.data); err != nil {
				return err
			}
		}
	}
	data, err := json.MarshalIndent(tx, "", "  ")
	if err != nil {
		return err
	}
	if err := atomicWrite(filepath.Join(dir, "journal.json"), append(data, '\n')); err != nil {
		return err
	}
	if prepared {
		// Publish only complete recovery state. Interrupted preparation changes no files.
		if err := os.Rename(dir, p.file("transaction")); err != nil {
			return err
		}
	}
	return errors.Join(syncDir(p.state), syncDir(filepath.Dir(p.state)))
}

func readTransaction(p paths) (transaction, error) {
	var tx transaction
	data, err := os.ReadFile(p.file("transaction/journal.json"))
	if err != nil {
		return tx, err
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&tx); err != nil {
		return tx, err
	}
	if err := decoder.Decode(new(any)); !errors.Is(err, io.EOF) {
		return tx, errors.New("journal must contain one JSON object")
	}
	if tx.Version != 1 || (tx.Phase != "prepared" && tx.Phase != "loading" && tx.Phase != "applied") || tx.PreviousSource == nil || tx.CandidateSource == nil || tx.CandidateGenerated == nil || !json.Valid(tx.CandidateActive) || tx.Reload && !json.Valid(tx.PreviousActive) {
		return tx, errors.New("invalid transaction journal")
	}
	return tx, nil
}

func checkTransactionFiles(p paths, tx transaction) error {
	for _, file := range []struct {
		path                string
		previous, candidate []byte
	}{
		{p.config, tx.PreviousSource, tx.CandidateSource}, {p.file("Caddyfile"), tx.PreviousGenerated, tx.CandidateGenerated},
	} {
		current, err := readOptional(file.path)
		if err != nil {
			return err
		}
		if !sameFileBytes(current, file.previous) && !sameFileBytes(current, file.candidate) {
			return fmt.Errorf("manual edit conflict at %s; recovery files: %s", file.path, p.file("transaction"))
		}
	}
	return nil
}

func sameFileBytes(a, b []byte) bool {
	return (a == nil) == (b == nil) && bytes.Equal(a, b)
}

// Link a flushed temporary file to publish the backup without overwriting it.
func createBackup(path string, data []byte) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".backup-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	_, writeErr := file.Write(data)
	if err := errors.Join(writeErr, file.Sync(), file.Close()); err != nil {
		return err
	}
	if err := os.Link(file.Name(), path); err != nil {
		return err
	}
	return syncDir(filepath.Dir(path))
}

func checkMigrationBackup(p paths, tx transaction) error {
	if !tx.Migration {
		return nil
	}
	backup := filepath.Join(filepath.Dir(p.config), "config.v1.backup.json")
	existing, err := readOptional(backup)
	if err != nil {
		return err
	}
	if existing != nil && !bytes.Equal(existing, tx.PreviousSource) {
		return fmt.Errorf("legacy backup conflict at %s; recovery files: %s", backup, p.file("transaction"))
	}
	return nil
}

func finishTransaction(p paths, tx transaction, candidate bool) error {
	if err := checkTransactionFiles(p, tx); err != nil {
		return err
	}
	source, generated := tx.PreviousSource, tx.PreviousGenerated
	if candidate {
		if err := checkMigrationBackup(p, tx); err != nil {
			return err
		}
		source, generated = tx.CandidateSource, tx.CandidateGenerated
		if tx.Migration {
			backup := filepath.Join(filepath.Dir(p.config), "config.v1.backup.json")
			existing, err := readOptional(backup)
			if err != nil {
				return err
			}
			if existing != nil && !bytes.Equal(existing, tx.PreviousSource) {
				return fmt.Errorf("legacy backup conflict at %s; recovery files: %s", backup, p.file("transaction"))
			}
			if existing == nil {
				if err := createBackup(backup, tx.PreviousSource); err != nil {
					return err
				}
			}
		}
	}
	for _, file := range []struct {
		path string
		data []byte
	}{{p.file("Caddyfile"), generated}, {p.config, source}} {
		current, err := readOptional(file.path)
		if err != nil {
			return err
		}
		// Recheck both files before each replacement after any prior I/O.
		if err := checkTransactionFiles(p, tx); err != nil {
			return err
		}
		if sameFileBytes(current, file.data) {
			continue
		}
		if file.data == nil {
			if err := os.Remove(file.path); err != nil && !errors.Is(err, os.ErrNotExist) {
				return err
			}
			if err := syncDir(filepath.Dir(file.path)); err != nil {
				return err
			}
		} else if err := atomicWrite(file.path, file.data); err != nil {
			return err
		}
	}
	// Detach the journal atomically only after committed directories are durable.
	completed := p.file("transaction-complete")
	if err := os.RemoveAll(completed); err != nil {
		return err
	}
	if err := os.Rename(p.file("transaction"), completed); err != nil {
		return err
	}
	if err := syncDir(p.state); err != nil {
		return err
	}
	if err := os.RemoveAll(completed); err != nil {
		return err
	}
	return syncDir(p.state)
}

func recoverTransaction(p paths, errOut io.Writer) error {
	_, err := os.Stat(p.file("transaction"))
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	tx, err := readTransaction(p)
	if err != nil {
		return fmt.Errorf("read recovery journal at %s: %w", p.file("transaction"), err)
	}
	if err := checkTransactionFiles(p, tx); err != nil {
		return err
	}
	candidate := tx.Phase == "applied"
	if tx.Reload {
		active, err := readActiveConfig(p)
		switch {
		case err == nil && jsonEqual(active, tx.CandidateActive):
			candidate = true
		case err == nil && jsonEqual(active, tx.PreviousActive):
			candidate = false
		case isRouterStopped(err):
			// An interrupted load without a durable acknowledgement restores old files.
		case err == nil:
			return fmt.Errorf("active configuration differs from both previous and candidate configurations; recovery files: %s", p.file("transaction"))
		default:
			return fmt.Errorf("cannot establish active router configuration; recovery files: %s: %v", p.file("transaction"), err)
		}
	}
	if err := finishTransaction(p, tx, candidate); err != nil {
		return err
	}
	fmt.Fprintln(errOut, "sandbar: recovered route transaction")
	return nil
}
